    { const char * tb_v1562 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v1562; }
    { const char * tb_v1563 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v1563; }
