    { const char * tb_v1785 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v1785; }
    { const char * tb_v1786 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v1786; }
