    { const char * tb_v2275 = "        secs.append(dict(name=name, type=typ, flags=flags, off=off, size=size, link=link, info=info, align=max(al, 1), addr=None))\n"; *(const char * *)tb_grow(v_lines) = tb_v2275; }
