    { const char * tb_v2300 = "    syms_extra = {}\n"; *(const char * *)tb_grow(v_lines) = tb_v2300; }
    { const char * tb_v2301 = "    addr = 0x100000\n"; *(const char * *)tb_grow(v_lines) = tb_v2301; }
